const $=s=>document.querySelector(s);let current=-1,S={},done=JSON.parse(localStorage.getItem('paradox-wins')||'[]');
const games=[['Your future self','TIME LOOPS','◷ ◷','Record a past self. Cooperate across time to open the exit.','Record a route to the gold plate, then wait there. Rewind and race to the exit while your echo holds the door.'],['Five realities','WORLD SHIFT','◇ ◈','One room, five rule sets. Find a path through their overlap.','A blocked move still counts. Switch worlds whenever a barrier stops you. The exit only exists in reality V.'],['The lying rulebook','DEDUCTION','≠ ?','Four statements are true. One lie conceals a three-digit code.','The code is 426. Statement 4 is false: the middle digit is even.'],['Alien machine','LANGUAGE','⟐ ⊕','Learn an unknown machine language, then write its program.','⊕ adds 2. ⟐ triples. ⊖ subtracts 1. From 1: ⊕ ⟐ ⊖ ⟐ gives 24.'],['Impossible inventory','RECURSION','□ ∞','Fold a room, invert a key, and unpack a spatial paradox.','Take the key. Mirror it. Fold the room. Put the key in the box. Enter the box and unlock the inner door.'],['Every possible future','SUPERPOSITION','⑂ →','One command moves two worlds. Bring every future home.','World A moves +1 / −1. World B moves +2 / −1. At the boundaries movement is clamped. Try six Rights, then one Left.']];
function score(){$('#score').textContent=done.length+' / 6 SOLVED'}
function home(){current=-1;score();$('#app').innerHTML=`<div class="eyebrow">A PLAYGROUND FOR DIFFICULT THINKING</div><h1>Question everything.<br><em>Especially the rules.</em></h1><p class="intro">Six small experiments in time, logic, and impossible space. Simple controls. Uncomfortable conclusions.</p><div class="sectionline"><span class="eyebrow">SELECT AN EXPERIMENT</span><span class="eyebrow">01—06 / MVP EDITION</span></div><div class="cards">${games.map((g,i)=>`<button class="card" onclick="openGame(${i})"><span class="number">0${i+1} / ${g[1]}</span><span class="arrow">${done.includes(i)?'✓':'↗'}</span><div class="symbol">${g[2]}</div><h2>${g[0]}</h2><p>${g[3]}</p></button>`).join('')}</div>`}
function openGame(i){current=i;S={p:[1,3],t:0,path:[[1,3]],echo:null,world:0,code:'',n:1,program:[],key:'floor',fold:false,inside:false,a:0,b:0,moves:0};score();$('#app').innerHTML=`<button onclick="home()">← All experiments</button><div class="eyebrow" style="margin-top:30px">EXPERIMENT 0${i+1} / ${games[i][1]}</div><h1 style="font-size:48px;letter-spacing:-2px">${games[i][0]}</h1><div class="playlayout"><div><div class="arena" id="arena"></div><div class="toolbar"><button onclick="openGame(current)">↺ Reset</button><button onclick="hint()">Reveal hint</button></div><div id="hint"></div></div><aside class="side"><h3>The experiment</h3><p id="rules"></p><h3>Objective</h3><p id="objective"></p><div class="status" id="result" role="status" aria-live="polite"></div></aside></div>`;render()}
function hint(){$('#hint').innerHTML='<p class="hint">'+games[current][4]+'</p>'}
function win(){if(!done.includes(current)){done.push(current);localStorage.setItem('paradox-wins',JSON.stringify(done));score()}$('#result').innerHTML='✓ Experiment solved.<br><button class="primary" onclick="'+(current<5?'openGame('+(current+1)+')':'home()')+'">'+(current<5?'Next experiment →':'Back to collection')+'</button>'}
function textRules(r,o){$('#rules').textContent=r;$('#objective').textContent=o}
function controls(){return `<div class="controls"><button aria-label="Move left" onclick="move(-1,0)">←</button><button aria-label="Move up" onclick="move(0,-1)">↑</button><button aria-label="Move down" onclick="move(0,1)">↓</button><button aria-label="Move right" onclick="move(1,0)">→</button><button onclick="move(0,0)">Wait</button></div>`}
function board(){let out='<div class="grid">';for(let y=0;y<7;y++)for(let x=0;x<7;x++){let wall=x===0||y===0||x===6||y===6;let e=S.echo&&S.echo[Math.min(S.t,S.echo.length-1)],at=S.p[0]===x&&S.p[1]===y;let ch='',cl='';if(current===0){if(x===3&&y!==3)wall=true;if(x===3&&y===3){ch='▥';cl='plate'}if(x===1&&y===1){ch='⊙';cl='plate'}if(x===5&&y===3){ch='↗';cl='goal'}}else{wall=wall||barrier(x,y,S.world);if(x===5&&y===5){ch='↗';cl='goal'}}if(e&&e[0]===x&&e[1]===y){ch='◌';cl+=' ghost'}if(at){ch='●';cl+=' you'}out+=`<div class="cell ${wall?'wall':cl}">${wall?'':ch}</div>`}return out+'</div>'}
function barrier(x,y,w){return (x===2&&y!==[1,2,3,4,5][w])||(x===4&&y!==[5,4,3,2,1][w])}
function render(){let a=$('#arena');if(current===0){textRules('Move with arrows or WASD. Your first run records a path. Rewind makes an echo repeat that path, one step per move. It stays at the last position. The gold plate opens the center door only while occupied.','Reach the green exit on the right while your echo stands on the plate at top left.');a.innerHTML=board()+`<span class="tag">TURN ${S.t} / ${S.echo?'ECHO ACTIVE':'RECORDING'}</span>`+controls()+`<button class="primary" onclick="rewind()">Rewind & create echo</button>`}if(current===1){textRules('The two walls have different openings in each reality. You may switch reality in place, but cannot switch into a wall. Your position is shared.','Reach the bottom-right exit in reality V.');a.innerHTML=`<span class="tag">REALITY ${['I','II','III','IV','V'][S.world]}</span>`+board()+controls()+`<div class="controls">${[0,1,2,3,4].map(w=>`<button class="${w===S.world?'primary':''}" onclick="shift(${w})">${w+1}</button>`).join('')}</div>`}if(current===2){textRules('The lock has three digits, each 1–6. Exactly one statement below is false. Repeated digits are allowed. Use the facts to deduce the unique code.','Enter the code and identify the false statement.');a.innerHTML=['The digits sum to 12.','The first digit is twice the second.','The last digit is 6.','The middle digit is odd.','The last digit is the first plus 2.'].map((r,i)=>`<div class="rule">0${i+1} — ${r}</div>`).join('')+`<label>Code <input id="code" inputmode="numeric" maxlength="3" placeholder="123" aria-label="Three digit code"></label><label>False statement <select id="lie">${[1,2,3,4,5].map(n=>`<option>${n}</option>`).join('')}</select></label><button class="primary" onclick="checkCode()">Test lock</button>`}if(current===3){textRules('Start at 1. Explore what the three glyphs do to the machine value. Reset whenever you want. The diagnostic log records each transformation.','Reach exactly 24 in four operations.');a.innerHTML=`<span class="tag">MACHINE OUTPUT / ${S.program.length} OF 4 OPERATIONS</span><div class="token">${S.n}</div><div class="controls">${['⊕','⟐','⊖'].map((t,i)=>`<button class="token" onclick="alien(${i})">${t}</button>`).join('')}</div><span>${S.program.join(' → ')||'Awaiting input'}</span>`}if(current===4){textRules('A silver key opens the outer room, but the exit is inside the portable room. The mirror reverses the key. A folded room becomes a box you can enter. Only objects packed inside travel with you.','Enter the folded room with a gold key and unlock its inner exit.');a.innerHTML=`<div class="symbol token">${S.inside?'⊡':S.fold?'□':'▱'} ${S.key==='floor'?'⚿':S.key==='packed'?'▣':'⚿'}</div><span class="tag">${S.inside?'INSIDE THE BOX':S.fold?'ROOM FOLDED':'OUTER CHAMBER'}</span><p>Key: ${S.key}. ${S.gold?'Gold / reversed':'Silver / ordinary'}.</p><div class="toolbar"><button onclick="inventory('take')">Take key</button><button onclick="inventory('mirror')">Use mirror</button><button onclick="inventory('fold')">Fold room</button><button onclick="inventory('pack')">Pack key</button><button onclick="inventory('enter')">Enter box</button><button class="primary" onclick="inventory('unlock')">Unlock exit</button></div>`}if(current===5){textRules('Two futures share your commands. Right moves A by 1 and B by 2. Left moves both by 1. Edges clamp movement to positions 0–6.','Put both markers at position 5 at the same time.');a.innerHTML=`<div class="branches">${['a','b'].map(k=>`<div><p class="tag">FUTURE ${k.toUpperCase()}</p><div class="track">${Array.from({length:7},(_,i)=>`<div class="dot ${S[k]===i?'active':''}">${S[k]===i?'●':i===5?'◎':i}</div>`).join('')}</div></div>`).join('')}</div><div class="toolbar"><button onclick="branch(-1)">← Left</button><button class="primary" onclick="branch(1)">Right →</button></div><span class="tag">${S.moves} COMMANDS</span>`}}
function msg(t){$('#result').textContent=t}
function move(dx,dy){if(current!==0&&current!==1)return;let [x,y]=S.p,nx=x+dx,ny=y+dy,ok=nx>0&&ny>0&&nx<6&&ny<6;if(current===0){let e=S.echo&&S.echo[Math.min(S.t+1,S.echo.length-1)];if(nx===3&&(ny!==3||!(e&&e[0]===1&&e[1]===1)))ok=false}else if(barrier(nx,ny,S.world))ok=false;if(ok)S.p=[nx,ny];S.t++;if(!S.echo)S.path.push([...S.p]);render();if(current===0&&S.p[0]===5&&S.p[1]===3)win();if(current===1&&S.p[0]===5&&S.p[1]===5&&S.world===4)win()}
function rewind(){S.echo=S.path.map(p=>[...p]);S.p=[1,3];S.t=0;render()}
function shift(w){if(barrier(...S.p,w)){msg('That reality has a wall at your position.');return}S.world=w;render();if(S.p[0]===5&&S.p[1]===5&&w===4)win()}
function checkCode(){if($('#code').value==='426'&&$('#lie').value==='4')win();else msg('The lock rejects this code / statement combination.')}
function alien(i){if(S.program.length>=4){msg('Four operations used. Reset to try another program.');return}let before=S.n;S.n=[S.n+2,S.n*3,S.n-1][i];S.program.push(before+' '+['⊕','⟐','⊖'][i]+' '+S.n);render();if(S.n===24&&S.program.length===4)win();else if(S.program.length===4)msg('Target missed. Reset to try a new sequence.')}
function inventory(a){let m='';if(a==='take'){if(S.key==='floor'&&!S.inside)S.key='held';else m='No loose key here.'}if(a==='mirror'){if(S.key==='held'&&!S.inside)S.gold=!S.gold;else m='Hold the key in the outer room to mirror it.'}if(a==='fold'){if(!S.inside)S.fold=true;else m='You cannot fold the room from inside.'}if(a==='pack'){if(S.fold&&S.key==='held'&&!S.inside)S.key='packed';else m='Hold the key and fold the room first.'}if(a==='enter'){if(S.fold)S.inside=true;else m='The room must become a box first.'}render();if(a==='unlock'){if(S.inside&&S.key==='packed'&&S.gold){win();return}m='The inner exit requires a gold key packed inside the box.'}msg(m)}
function branch(d){S.a=Math.max(0,Math.min(6,S.a+d));S.b=Math.max(0,Math.min(6,S.b+(d>0?2:-1)));S.moves++;render();if(S.a===5&&S.b===5)win()}
document.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;let d={ArrowLeft:[-1,0],a:[-1,0],ArrowRight:[1,0],d:[1,0],ArrowUp:[0,-1],w:[0,-1],ArrowDown:[0,1],s:[0,1]};if(d[e.key]&&(current===0||current===1)){e.preventDefault();move(...d[e.key])}});home();
